CREATE TABLE customer_po_documents(id uuid PRIMARY KEY,owner_id uuid NOT NULL REFERENCES users(id),filename text NOT NULL,mime text NOT NULL CHECK(mime IN('application/pdf','image/png','image/jpeg')),sha256 text NOT NULL,content bytea NOT NULL CHECK(octet_length(content)>0 AND octet_length(content)<=8388608),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE ipo_submissions(id uuid PRIMARY KEY,input jsonb NOT NULL,snapshot jsonb NOT NULL,fingerprint text NOT NULL,request_key uuid UNIQUE NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE customer_purchase_orders(id uuid PRIMARY KEY,quotation_id uuid REFERENCES quotation_versions(id),boq_revision_id uuid REFERENCES boq_revisions(id),customer_id integer NOT NULL REFERENCES customers(id),po_number text NOT NULL,document_id uuid REFERENCES customer_po_documents(id),input jsonb NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now(),CHECK((quotation_id IS NULL)=(boq_revision_id IS NULL)));
CREATE UNIQUE INDEX customer_po_reference_unique ON customer_purchase_orders(customer_id,po_number) WHERE po_number<>'';
CREATE TABLE internal_purchase_orders(id uuid PRIMARY KEY,customer_po_id uuid UNIQUE NOT NULL REFERENCES customer_purchase_orders(id),submission_id uuid UNIQUE REFERENCES ipo_submissions(id),number text UNIQUE NOT NULL,snapshot jsonb NOT NULL,fingerprint text NOT NULL,request_key uuid UNIQUE NOT NULL,created_by uuid NOT NULL REFERENCES users(id),created_at timestamptz NOT NULL DEFAULT now());
CREATE TRIGGER immutable_ipo_submission BEFORE UPDATE OR DELETE ON ipo_submissions FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
CREATE TRIGGER immutable_po_document BEFORE UPDATE OR DELETE ON customer_po_documents FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
CREATE TRIGGER immutable_customer_po BEFORE UPDATE OR DELETE ON customer_purchase_orders FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
CREATE TRIGGER immutable_ipo BEFORE UPDATE OR DELETE ON internal_purchase_orders FOR EACH ROW EXECUTE FUNCTION prevent_master_version_mutation();
